window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-276a318cfc946c9f"]={"versions": [{"id": "FIG-276a318cfc946c9f", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration) des AUTOSAR Diagnostic Event Manager (Dem) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Konfigurationsstruktur der zeitbasierten Entprellungsklasse <code>DemDebounceTimeBaseClass</code> und deren Einbettung in das übergeordnete <code>DemConfigSet</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Konfigurationsentitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DemConfigSet</code> (<code>EcucParamConfContainerDef</code>): Übergeordneter Konfigurationscontainer.\n</li><li><code>DemDebounceTimeBaseClass</code> (<code>EcucParamConfContainerDef</code>): Subcontainer (<code>+subContainer</code>), untergeordnet an <code>DemConfigSet</code> mit Multiplizität 0..65535 (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 65535</code>), ohne weitere enthaltene Subcontainer („No Included Containers“).\n</li><li>Zugeordnete Konfigurationsparameter (<code>+parameter</code>):\n<ul class=\"fig-list\"><li><code>DemDebounceTimeFailedThreshold</code> (<code>EcucFloatParamDef</code>): Gleitkommaparameter mit Schwellenwertbereich <code>min = 0.001</code> bis <code>max = 3600.0</code>.\n</li><li><code>DemDebounceTimePassedThreshold</code> (<code>EcucFloatParamDef</code>): Gleitkommaparameter mit Schwellenwertbereich <code>min = 0.001</code> bis <code>max = 3600.0</code>.\n</li><li><code>DemDebounceBehavior</code> (<code>EcucEnumerationParamDef</code>): Aufzählungsparameter mit Multiplizität 1..1 (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>DemTimeBasedFdcThresholdStorageValue</code> (<code>EcucFloatParamDef</code>): Optionaler Gleitkommaparameter mit Multiplizität 0..1 (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) und Wertebereich <code>min = 0.001</code> bis <code>max = 3600</code>.\n</li></ul>\n</li><li>Aufzählungsliterale (<code>+literal</code>) für <code>DemDebounceBehavior</code>:\n<ul class=\"fig-list\"><li><code>DEM_DEBOUNCE_FREEZE</code> (<code>EcucEnumerationLiteralDef</code>)\n</li><li><code>DEM_DEBOUNCE_RESET</code> (<code>EcucEnumerationLiteralDef</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell enthält das Diagramm keine direkten Laufzeit- oder Sequenzabläufe. Die modellierten Parameter steuern das zeitbasierte Entprellverhalten im Dem-BSW-Modul:</p>\n<ul class=\"fig-list\"><li><code>DemDebounceTimeFailedThreshold</code> und <code>DemDebounceTimePassedThreshold</code> definieren die Zeitdauern, die ein Fehlereignis kontinuierlich anstehen bzw. geheilt sein muss, bevor der Ereignisstatus von pre-failed/pre-passed auf failed bzw. passed wechselt.\n</li><li><code>DemDebounceBehavior</code> bestimmt, ob der Entprelltimer bei Unterbrechung der Qualifikationsbedingungen einfriert (<code>DEM_DEBOUNCE_FREEZE</code>) oder auf den Initialwert zurückgesetzt wird (<code>DEM_DEBOUNCE_RESET</code>).\n</li><li><code>DemTimeBasedFdcThresholdStorageValue</code> legt den Schwellenwert für das vorzeitige Zwischenspeichern (Fault Detection Counter / Freeze Frame Storage) fest.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für BSW-Konfigurations- und Codegenerator-Werkzeuge des AUTOSAR Dem. Konfigurationsdateien müssen bei Instanziierung einer zeitbasierten Entprellklasse die definierten Grenzen einhalten:</p>\n<ul class=\"fig-list\"><li>Schwellenwerte für Passed- und Failed-Zeiten müssen im Intervall [0.001, 3600.0] Sekunden liegen.\n</li><li><code>DemDebounceBehavior</code> ist verpflichtend mit Kardinalität 1 zu konfigurieren und erlaubt ausschließlich die Literale <code>DEM_DEBOUNCE_FREEZE</code> oder <code>DEM_DEBOUNCE_RESET</code>. Ein Default-Wert ist im Modell nicht vorgegeben.\n</li><li><code>DemTimeBasedFdcThresholdStorageValue</code> ist optional. Bis zu 65535 zeitbasierte Entprellklassen können pro <code>DemConfigSet</code> definiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e34fe318544d03dc", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration) des AUTOSAR Diagnostic Event Manager (Dem) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Konfigurationsstruktur der zeitbasierten Entprellungsklasse <code>DemDebounceTimeBaseClass</code> und deren Einbettung in das übergeordnete <code>DemConfigSet</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Konfigurationsentitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DemConfigSet</code> (<code>EcucParamConfContainerDef</code>): Übergeordneter Konfigurationscontainer.\n</li><li><code>DemDebounceTimeBaseClass</code> (<code>EcucParamConfContainerDef</code>): Subcontainer (<code>+subContainer</code>), untergeordnet an <code>DemConfigSet</code> mit Multiplizität 0..65535 (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 65535</code>), ohne weitere enthaltene Subcontainer („No Included Containers“).\n</li><li>Zugeordnete Konfigurationsparameter (<code>+parameter</code>):\n<ul class=\"fig-list\"><li><code>DemDebounceTimeFailedThreshold</code> (<code>EcucFloatParamDef</code>): Gleitkommaparameter mit Schwellenwertbereich <code>min = 0.001</code> bis <code>max = 3600.0</code>.\n</li><li><code>DemDebounceTimePassedThreshold</code> (<code>EcucFloatParamDef</code>): Gleitkommaparameter mit Schwellenwertbereich <code>min = 0.001</code> bis <code>max = 3600.0</code>.\n</li><li><code>DemDebounceBehavior</code> (<code>EcucEnumerationParamDef</code>): Aufzählungsparameter mit Multiplizität 1..1 (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>) und Standardwert <code>defaultValue = DEM_DEBOUNCE_RESET</code>.\n</li><li><code>DemTimeBasedFdcThresholdStorageValue</code> (<code>EcucFloatParamDef</code>): Optionaler Gleitkommaparameter mit Multiplizität 0..1 (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) und Wertebereich <code>min = 0.001</code> bis <code>max = 3600</code>.\n</li></ul>\n</li><li>Aufzählungsliterale (<code>+literal</code>) für <code>DemDebounceBehavior</code>:\n<ul class=\"fig-list\"><li><code>DEM_DEBOUNCE_FREEZE</code> (<code>EcucEnumerationLiteralDef</code>)\n</li><li><code>DEM_DEBOUNCE_RESET</code> (<code>EcucEnumerationLiteralDef</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell enthält das Diagramm keine direkten Laufzeit- oder Sequenzabläufe. Die modellierten Parameter steuern das zeitbasierte Entprellverhalten im Dem-BSW-Modul:</p>\n<ul class=\"fig-list\"><li><code>DemDebounceTimeFailedThreshold</code> und <code>DemDebounceTimePassedThreshold</code> definieren die Zeitdauern, die ein Fehlereignis kontinuierlich anstehen bzw. geheilt sein muss, bevor der Ereignisstatus von pre-failed/pre-passed auf failed bzw. passed wechselt.\n</li><li><code>DemDebounceBehavior</code> bestimmt, ob der Entprelltimer bei Unterbrechung der Qualifikationsbedingungen einfriert (<code>DEM_DEBOUNCE_FREEZE</code>) oder auf den Initialwert zurückgesetzt wird (<code>DEM_DEBOUNCE_RESET</code>).\n</li><li><code>DemTimeBasedFdcThresholdStorageValue</code> legt den Schwellenwert für das vorzeitige Zwischenspeichern (Fault Detection Counter / Freeze Frame Storage) fest.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für BSW-Konfigurations- und Codegenerator-Werkzeuge des AUTOSAR Dem. Konfigurationsdateien müssen bei Instanziierung einer zeitbasierten Entprellklasse die definierten Grenzen einhalten:</p>\n<ul class=\"fig-list\"><li>Schwellenwerte für Passed- und Failed-Zeiten müssen im Intervall [0.001, 3600.0] Sekunden liegen.\n</li><li><code>DemDebounceBehavior</code> ist verpflichtend mit Kardinalität 1 zu konfigurieren und erlaubt ausschließlich die Literale <code>DEM_DEBOUNCE_FREEZE</code> oder <code>DEM_DEBOUNCE_RESET</code>. Standardmäßig ist <code>defaultValue = DEM_DEBOUNCE_RESET</code> vorgesehen.\n</li><li><code>DemTimeBasedFdcThresholdStorageValue</code> ist optional. Bis zu 65535 zeitbasierte Entprellklassen können pro <code>DemConfigSet</code> definiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-276a318cfc946c9f", "to": "FIG-e34fe318544d03dc", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Parameter <code>DemDebounceBehavior</code>: Attribut <code>defaultValue = DEM_DEBOUNCE_RESET</code> ergänzt.\n</li></ul>"}]};
